import{_ as r,o as s,c as i,ak as l,bU as a,bV as t,bW as u}from"./chunks/framework.BnR3M3Bd.js";const g=JSON.parse('{"title":"Ajout de lumières 2D","description":"","frontmatter":{},"headers":[],"relativePath":"23_Lumieres2d.md","filePath":"23_Lumieres2d.md","lastUpdated":1769182706000}'),o={name:"23_Lumieres2d.md"};function n(d,e,m,p,c,f){return s(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="ajout-de-lumieres-2d" tabindex="-1">Ajout de lumières 2D <a class="header-anchor" href="#ajout-de-lumieres-2d" aria-label="Permalink to “Ajout de lumières 2D”">​</a></h1><p>Les lumières peuvent ajouterz une dimension supplémentaire à vos scènes 2D en créant des effets d&#39;éclairage réalistes. Unity offre plusieurs types de lumières 2D que vous pouvez utiliser pour améliorer l&#39;apparence de vos jeux.</p><p><img src="'+a+'" alt="Sans lumières"></p><p><img src="'+t+'" alt="Avec lumières"></p><h2 id="ajouter-une-lumiere-2d" tabindex="-1">Ajouter une lumière 2D <a class="header-anchor" href="#ajouter-une-lumiere-2d" aria-label="Permalink to “Ajouter une lumière 2D”">​</a></h2><p>Dans le menu principal, allez dans <strong>GameObject &gt; Light &gt; 2D</strong> et choisissez le type de lumière que vous souhaitez ajouter (Freeform Light 2D, Spot Light 2D, Global Light 2D, etc.). Une nouvelle lumière sera ajoutée à votre scène.</p><p><img src="'+u+'" alt="Types de lumières 2D"></p><h3 id="types-de-lumieres-2d" tabindex="-1">Types de lumières 2D <a class="header-anchor" href="#types-de-lumieres-2d" aria-label="Permalink to “Types de lumières 2D”">​</a></h3><ul><li><strong>Freeform Light 2D</strong> : Permet de créer des formes de lumière personnalisées en dessinant directement dans la scène. Vous pouvez contrôler la forme de la lumière en ajustant les points de contrôle.</li><li><strong>Spot Light 2D</strong> : Émet de la lumière dans un cône à partir d&#39;un point spécifique. Parfait pour simuler des projecteurs ou des lampes de poche. Vous pouvez ajuster l&#39;angle et la portée du cône.</li><li><strong>Global Light 2D</strong> : Émet une lumière uniforme sur toute la scène uniformément. Utile pour simuler la lumière ambiante ou la lumière du jour.</li><li><strong>Sprite Light 2D</strong> : Utilise une texture de sprite pour définir la forme et l&#39;apparence de la lumière. Idéal pour des effets de lumière stylisés ou spécifiques avec une forme particulière.</li></ul><h2 id="configurer-une-lumiere-2d" tabindex="-1">Configurer une lumière 2D <a class="header-anchor" href="#configurer-une-lumiere-2d" aria-label="Permalink to “Configurer une lumière 2D”">​</a></h2><p>Sélectionnez la lumière 2D dans la hiérarchie pour afficher ses propriétés dans l&#39;inspecteur. Vous pouvez ajuster les paramètres suivants :</p><ul><li><strong>Color</strong> : Changez la couleur de la lumière.</li><li><strong>Intensity</strong> : Ajustez la luminosité de la lumière.</li><li><strong>Falloff</strong> : Contrôlez la distance à laquelle la lumière affecte les objets.</li><li><strong>Shadow Type</strong> : Choisissez le type d&#39;ombre (None, Hard, Soft).</li><li><strong>Sorting Layer</strong> : Définissez la couche de tri pour la lumière afin de contrôler son ordre de rendu par rapport aux autres objets. Vous pourriez ainsi appliquer des effets d&#39;éclairage sur le personnage sans affecter l&#39;arrière-plan.</li></ul><h2 id="trucs-et-astuces" tabindex="-1">Trucs et astuces <a class="header-anchor" href="#trucs-et-astuces" aria-label="Permalink to “Trucs et astuces”">​</a></h2><ul><li>Utilisez des lumières Global Light 2D pour éclairer toute la scène de manière uniforme en premier et diminuer l&#39;intensité pour créer une ambiance.</li><li>Combinez plusieurs types de lumières 2D pour obtenir des effets d&#39;éclairage plus complexes.</li><li>Combinez les lumières 2D avec des effets de post-traitement (bloom et screen space lens flare) pour améliorer l&#39;apparence visuelle de votre scène.</li></ul><p><a href="https://docs.unity3d.com/Manual/urp/LightTypes.html" target="_blank" rel="noreferrer">Documents officiels Unity sur les lumières 2D</a></p>',15)])])}const _=r(o,[["render",n]]);export{g as __pageData,_ as default};
